bounded_host_request.command:
set -eu
new=create-videobot:duplicate-guard-87ee908e-stage
test -n "$(docker images -q "$new")" || exit 60
docker run --rm --network none -w /opt/videobot --entrypoint node "$new" --input-type=module -e '
import {publishVideoListing} from "./src/telegram/paidListingPublisher.mjs";
import {createPostgresPostingReceiptStore} from "./src/sales/pgPostingReceipts.mjs";
let phase=0,events=0;
const listing={id:"sale001",sellerId:"user1",revision:2,title:"Test",thumbnail:{fileId:"photo001"},sample:{fileId:"sample001",durationSeconds:30},paidVideo:{fileId:"paid001"},priceStars:10,rightsVerified:true,adultConsentVerified:true,ownerConfirmedPublish:true,feeTermsAccepted:true,managementFeeBps:3000};
const store={read:async()=>null,claim:async()=>{events++;return {claimed:true}},findOtherDelivery:async()=>({key:"sale001:1",status:"sent"}),recordFree:async()=>{},recordPaid:async()=>{},markUnknown:async()=>{}};
try {
 phase=1;
 await publishVideoListing({listing,store,getVerifiedVideoTopic:async()=>({id:1,purpose:"video_sale",board:"video_chat",enabled:true,verified:true,chatId:-100123,threadId:1,title:"Sale"}),telegramApi:async()=>{events++}});
 process.exitCode=80;
} catch(e) {
 if(e.message==="VIDEO_EXISTING_PUBLICATION_REQUIRES_EDIT"&&events===0)phase=2;
 else if(e.message.includes("fee agreement"))process.exitCode=81;
 else if(e.message.includes("sample"))process.exitCode=82;
 else if(e.message.includes("topic"))process.exitCode=83;
 else process.exitCode=84;
}
if(phase===2){
 const db=createPostgresPostingReceiptStore({query:async(sql)=>({rows:[{delivery_key:"sale001:1",status:"sent"}]})});
 if(typeof db.findOtherDelivery!=="function")process.exitCode=85;
 else{
  const other=await db.findOtherDelivery({listingId:"sale001",key:"sale001:2"});
  if(other?.key==="sale001:1")console.log("DUPLICATE_STAGE_MOCK_PASS=PASS");
  else process.exitCode=86;
 }
}
'
